mapper.select:
select rq.id, concat(#{orderPrefix}, lpad(rq.id, 12, '0')) as orderNo, #{category} as category, reg.real_name as patientName, reg.case_number as outpatientNo, tech.tech_name as itemName, dept.dept_name as department, doctor.realname as doctorName, date_format(rq.creation_time, '%Y-%m-%d %H:%i:%s') as appliedAt, rq.${fieldPrefix}_state as status, executor.realname as executor, date_format(rq.${fieldPrefix}_time, '%Y-%m-%d %H:%i:%s') as executedAt, rq.${fieldPrefix}_result as result from ${tableName} rq join register reg on reg.id = rq.register_id join medical_technology tech on tech.id = rq.medical_technology_id join department dept on dept.id = reg.deptment_id join employee doctor on doctor.id = rq.created_by left join employee executor on executor.id = rq.${fieldPrefix}_employee_id where rq.${fieldPrefix}_state in ('PAID', 'EXECUTING', 'COMPLETED') and rq.${fieldPrefix}_state = #{status}
and (reg.real_name like concat('%', #{keyword}, '%') or reg.case_number like concat('%', #{keyword}, '%') or tech.tech_name like concat('%', #{keyword}, '%'))
order by rq.creation_time desc, rq.id desc
